INSERT INTO `workflow_templates` (`name`, `description`, `category`, `tags`, `workflow_json`, `author_id`, `author_name`, `tenant_id`, `downloads`, `id`, `created_at`, `updated_at`) VALUES
  ('简单 LLM 对话', '入门级模板: 接收用户输入,调用 LLM 生成回复。导入后在 Inspector 里选择具体的 ModelConfig 即可运行。', 'chat', '["入门", "llm", "chat"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "llm_1"}, {"id": "e3", "source": "llm_1", "target": "output"}, {"id": "e4", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "user_input", "type": "string"}]}, "position": {"x": 0, "y": 80}}, {"id": "llm_1", "type": "llm", "config": {"title": "简单回复", "system_prompt": "你是一个乐于助人的助手。", "prompt_template": "用户说: {{ user_input }}\\n请给出友好的回复。"}, "position": {"x": 0, "y": 160}}, {"id": "output", "type": "output", "config": {"variable_name": "response"}, "position": {"x": 0, "y": 240}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 320}}]}', 1, 'Local Admin', 1, 0, 1, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  ('RAG 知识库问答', '经典 RAG 场景: 先从知识库检索相关文档,再让 LLM 基于检索结果回答。导入后需在 Inspector 里选 KB id 与 ModelConfig。', 'rag', '["rag", "知识库", "qa"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "kb_retrieve"}, {"id": "e3", "source": "input", "target": "llm_1"}, {"id": "e4", "source": "kb_retrieve", "target": "llm_1"}, {"id": "e5", "source": "llm_1", "target": "output"}, {"id": "e6", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "question", "type": "string"}]}, "position": {"x": 0, "y": 80}}, {"id": "kb_retrieve", "type": "knowledge_retrieval", "config": {"kb_id": null, "title": "知识库检索", "top_k": 5, "query_template": "{{ question }}"}, "position": {"x": 0, "y": 160}}, {"id": "llm_1", "type": "llm", "config": {"title": "基于检索结果回答", "system_prompt": "你是一个严谨的助手,请仅基于提供的参考资料回答问题。如果资料不足以回答,直接说「资料不足」。", "prompt_template": "用户问题: {{ question }}\\n\\n参考资料:\\n{{ kb_retrieve.chunks }}\\n\\n请给出回答。"}, "position": {"x": 0, "y": 240}}, {"id": "output", "type": "output", "config": {"variable_name": "answer"}, "position": {"x": 0, "y": 320}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 400}}]}', 1, 'Local Admin', 1, 0, 2, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  ('HTTP API 调用', '调用外部 HTTP API 获取数据,用 Jinja2 模板格式化输出。导入后在 HTTP 节点填 URL/Method,在模板节点调整字段。', 'integration', '["http", "api", "integration"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "http_1"}, {"id": "e2b", "source": "input", "target": "fmt"}, {"id": "e3", "source": "http_1", "target": "fmt"}, {"id": "e4", "source": "fmt", "target": "output"}, {"id": "e5", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "city", "type": "string"}]}, "position": {"x": 0, "y": 80}}, {"id": "http_1", "type": "http", "config": {"url": "https://api.example.com/weather", "query": {"city": "{{ city }}"}, "title": "查询天气", "method": "GET", "headers": {}}, "position": {"x": 0, "y": 160}}, {"id": "fmt", "type": "template_transform", "config": {"title": "格式化天气信息", "template": "{{ city }} 当前天气: {{ http_1.body.temp }}°C, {{ http_1.body.desc }}"}, "position": {"x": 0, "y": 240}}, {"id": "output", "type": "output", "config": {"variable_name": "weather_text"}, "position": {"x": 0, "y": 320}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 400}}]}', 1, 'Local Admin', 1, 0, 3, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  ('条件分支客服路由', '用 LLM 判断用户问题属于「售前」还是「售后」,分别走两条不同分支。导入后需给两个 LLM 节点选 ModelConfig,并在 Condition 节点配置 case 表达式。', 'control', '["condition", "routing", "分类"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "classify"}, {"id": "e2b", "source": "input", "target": "llm_presale"}, {"id": "e2c", "source": "input", "target": "llm_aftersale"}, {"id": "e3", "source": "classify", "target": "llm_presale", "condition": "category==presale"}, {"id": "e4", "source": "classify", "target": "llm_aftersale", "condition": "category==aftersale"}, {"id": "e5", "source": "llm_presale", "target": "output"}, {"id": "e6", "source": "llm_aftersale", "target": "output"}, {"id": "e7", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "user_query", "type": "string"}]}, "position": {"x": 0, "y": 80}}, {"id": "classify", "type": "question_classifier", "config": {"title": "意图分类", "question": "{{ user_query }}", "categories": [{"name": "presale", "description": "售前咨询: 价格、功能、购买建议"}, {"name": "aftersale", "description": "售后问题: 使用、故障、退换货"}], "model_config_id": null}, "position": {"x": 0, "y": 160}}, {"id": "llm_presale", "type": "llm", "config": {"title": "售前回复", "system_prompt": "你是售前顾问,回答用户关于产品功能、价格、购买建议的问题。", "prompt_template": "用户问题: {{ user_query }}"}, "position": {"x": -200, "y": 240}}, {"id": "llm_aftersale", "type": "llm", "config": {"title": "售后回复", "system_prompt": "你是售后工程师,帮助用户解决使用问题,排查故障,办理退换货。", "prompt_template": "用户问题: {{ user_query }}"}, "position": {"x": 200, "y": 240}}, {"id": "output", "type": "output", "config": {"variable_name": "reply"}, "position": {"x": 0, "y": 320}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 400}}]}', 1, 'Local Admin', 1, 0, 4, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  ('代码数据处理', '用受限沙箱里的 Python 脚本对输入数据做计算/转换。适合批量处理、结构化数据清洗。导入后在 Code 节点编辑 Python。', 'processing', '["code", "sandbox", "数据处理"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "code_1"}, {"id": "e3", "source": "code_1", "target": "fmt"}, {"id": "e4", "source": "fmt", "target": "output"}, {"id": "e5", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "numbers", "type": "list"}]}, "position": {"x": 0, "y": 80}}, {"id": "code_1", "type": "code", "config": {"code": "# input_data 包含上游变量,这里取 numbers 列表\\nnums = input_data.get(\'numbers\', [])\\nresult = {\\n  \'count\': len(nums),\\n  \'sum\': sum(nums),\\n  \'avg\': sum(nums) / len(nums) if nums else 0,\\n  \'sorted_desc\': sorted(nums, reverse=True),\\n}\\n", "title": "统计与排序"}, "position": {"x": 0, "y": 160}}, {"id": "fmt", "type": "template_transform", "config": {"title": "格式化统计结果", "template": "共 {{ code_1.result.count }} 个数, 总和 {{ code_1.result.sum }}, 平均 {{ code_1.result.avg }}"}, "position": {"x": 0, "y": 240}}, {"id": "output", "type": "output", "config": {"variable_name": "summary"}, "position": {"x": 0, "y": 320}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 400}}]}', 1, 'Local Admin', 1, 0, 5, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  ('模板渲染', '纯 Jinja2 模板渲染,不调用 LLM。适合做通知、报告、邮件、Slack 消息的格式化。', 'processing', '["template", "jinja2", "通知"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "fmt"}, {"id": "e3", "source": "fmt", "target": "output"}, {"id": "e4", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "user_name", "type": "string"}, {"name": "order_id", "type": "string"}, {"name": "amount", "type": "number"}]}, "position": {"x": 0, "y": 80}}, {"id": "fmt", "type": "template_transform", "config": {"title": "订单通知模板", "template": "尊敬的 {{ user_name }}:\\n\\n您的订单 {{ order_id }} 已提交,金额 ¥{{ amount }}。\\n我们会在 24 小时内处理,感谢您的信任!"}, "position": {"x": 0, "y": 160}}, {"id": "output", "type": "output", "config": {"variable_name": "notification_text"}, "position": {"x": 0, "y": 240}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 320}}]}', 1, 'Local Admin', 1, 0, 6, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  ('多步推理链', '两阶段 LLM: 第一阶段生成大纲,第二阶段基于大纲展开。适合长文写作、研究分析、复杂推理。', 'advanced', '["llm", "chain", "推理"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "llm_outline"}, {"id": "e2b", "source": "input", "target": "llm_expand"}, {"id": "e3", "source": "llm_outline", "target": "llm_expand"}, {"id": "e4", "source": "llm_expand", "target": "output"}, {"id": "e5", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "topic", "type": "string"}]}, "position": {"x": 0, "y": 80}}, {"id": "llm_outline", "type": "llm", "config": {"title": "生成大纲", "system_prompt": "你是一个结构化思考者,擅长把复杂主题拆成清晰的大纲。", "prompt_template": "主题: {{ topic }}\\n请输出 3-5 个要点的简短大纲,每点一行。"}, "position": {"x": 0, "y": 160}}, {"id": "llm_expand", "type": "llm", "config": {"title": "展开成文", "system_prompt": "你是一个专业写手,根据大纲写一篇结构清晰、语言流畅的文章。", "prompt_template": "主题: {{ topic }}\\n\\n大纲:\\n{{ llm_outline.response }}\\n\\n请基于以上大纲写一篇 500 字左右的文章。"}, "position": {"x": 0, "y": 240}}, {"id": "output", "type": "output", "config": {"variable_name": "article"}, "position": {"x": 0, "y": 320}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 400}}]}', 1, 'Local Admin', 1, 0, 7, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  ('参数提取', '用 LLM 从一段非结构化文本里提取结构化字段(姓名、电话、邮箱等)。导入后配置 ModelConfig + 输出 schema。', 'advanced', '["parameter", "extraction", "structured"]', '{"edges": [{"id": "e1", "source": "start", "target": "input"}, {"id": "e2", "source": "input", "target": "extract"}, {"id": "e3", "source": "extract", "target": "fmt"}, {"id": "e4", "source": "fmt", "target": "output"}, {"id": "e5", "source": "output", "target": "end"}], "nodes": [{"id": "start", "type": "start", "config": {}, "position": {"x": 0, "y": 0}}, {"id": "input", "type": "input", "config": {"variables": [{"name": "raw_text", "type": "string"}]}, "position": {"x": 0, "y": 80}}, {"id": "extract", "type": "parameter_extractor", "config": {"text": "{{ raw_text }}", "title": "提取联系人信息", "parameters": [{"name": "name", "type": "string", "required": true, "description": "人名"}, {"name": "phone", "type": "string", "required": false, "description": "电话号码"}, {"name": "email", "type": "string", "required": false, "description": "电子邮箱"}], "model_config_id": null}, "position": {"x": 0, "y": 160}}, {"id": "fmt", "type": "template_transform", "config": {"title": "汇总提取结果", "template": "提取结果: 姓名={{ extract.name }}; 电话={{ extract.phone | default(\'未提供\') }}; 邮箱={{ extract.email | default(\'未提供\') }}"}, "position": {"x": 0, "y": 240}}, {"id": "output", "type": "output", "config": {"variable_name": "extracted"}, "position": {"x": 0, "y": 320}}, {"id": "end", "type": "end", "config": {}, "position": {"x": 0, "y": 400}}]}', 1, 'Local Admin', 1, 0, 8, '2026-08-07 07:31:45', '2026-08-07 07:31:45');
INSERT INTO `wx_templates` (`tenant_id`, `name`, `category`, `description`, `html_body`, `css_variables`, `preview_html`, `thumbnail`, `is_system`, `created_by`, `usage_count`, `id`, `created_at`, `updated_at`) VALUES
  (1, '极简白板', 'minimal', '纯白底黑字,大留白,适合严肃长文与干货分享。', '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>{{title}}</title>\n<style>\n/* 模板样式 — 元素级 CSS + css_variables var(--*) 主题切换. */\nbody { background: var(--bg); color: var(--text); }\n.wx-article {\n  font-family: var(--font-family);\n  font-size: var(--font-size);\n  line-height: var(--line-height);\n  padding: var(--padding);\n  max-width: var(--max-width);\n  margin: 0 auto;\n  word-wrap: break-word;\n  overflow-wrap: break-word;\n}\n.wx-cover { margin: 0 0 1.2em 0; }\n.wx-cover img { width: 100%; border-radius: 6px; display: block; }\n.wx-title {\n  font-size: 1.6em;\n  font-weight: 700;\n  color: var(--accent);\n  border-bottom: 2px solid var(--accent);\n  padding-bottom: 0.5em;\n  margin: 1em 0 0.5em;\n  line-height: 1.3;\n}\n.wx-author {\n  color: var(--text);\n  opacity: 0.7;\n  font-size: 0.9em;\n  margin-bottom: 1.5em;\n  text-align: right;\n}\n.wx-content h1 {\n  font-size: 1.5em;\n  color: var(--accent);\n  border-left: 4px solid var(--accent);\n  padding-left: 12px;\n  margin: 2em 0 1em;\n  font-weight: var(--heading-weight, 700);\n}\n.wx-content h2 {\n  font-size: 1.3em;\n  color: var(--accent);\n  margin: 1.8em 0 0.8em;\n  font-weight: 600;\n}\n.wx-content h3 {\n  font-size: 1.15em;\n  color: var(--accent);\n  margin: 1.5em 0 0.6em;\n  font-weight: 600;\n}\n.wx-content h4, .wx-content h5, .wx-content h6 {\n  font-size: 1.05em;\n  color: var(--accent);\n  margin: 1.3em 0 0.5em;\n  font-weight: 600;\n}\n.wx-content p { margin: 1.2em 0; }\n.wx-content blockquote {\n  margin: 1.5em 0;\n  padding: 1em 1.5em;\n  background: var(--bg-secondary, rgba(0,0,0,0.03));\n  border-left: 4px solid var(--accent);\n  border-radius: 0 6px 6px 0;\n  color: var(--text);\n  opacity: 0.95;\n}\n.wx-content code {\n  background: var(--code-bg);\n  color: var(--code-text, var(--accent));\n  padding: 0.2em 0.4em;\n  border-radius: 3px;\n  font-family: var(--code-font, monospace);\n  font-size: 0.9em;\n}\n.wx-content pre {\n  background: var(--code-bg);\n  padding: 1.2em;\n  margin: 1.5em 0;\n  border-radius: 6px;\n  overflow: auto;\n  line-height: 1.5;\n}\n.wx-content pre code {\n  background: none;\n  padding: 0;\n  color: var(--code-text);\n  font-size: 0.9em;\n}\n.wx-content ul, .wx-content ol {\n  margin: 1em 0;\n  padding-left: 2em;\n}\n.wx-content li {\n  margin: 0.4em 0;\n  line-height: var(--line-height);\n}\n.wx-content ul li { list-style-type: var(--list-marker, disc); }\n.wx-content ol li { list-style-type: decimal; }\n.wx-content ul ul, .wx-content ol ol,\n.wx-content ul ol, .wx-content ol ul {\n  margin: 0.3em 0;\n}\n.wx-content table {\n  width: 100%;\n  border-collapse: collapse;\n  margin: 1.5em 0;\n  font-size: 0.95em;\n}\n.wx-content th, .wx-content td {\n  border: 1px solid var(--table-border, #e2e8f0);\n  padding: 8px 12px;\n  text-align: left;\n}\n.wx-content th {\n  background: var(--code-bg);\n  font-weight: 600;\n  color: var(--accent);\n}\n.wx-content a {\n  color: var(--accent);\n  text-decoration: none;\n  border-bottom: 1px solid var(--accent);\n}\n.wx-content a:hover {\n  opacity: 0.8;\n}\n.wx-content img {\n  max-width: 100%;\n  border-radius: 6px;\n  margin: 1.5em auto;\n  display: block;\n}\n.wx-content hr {\n  border: 0;\n  border-top: 1px solid var(--table-border, #e2e8f0);\n  margin: 2em 0;\n}\n.wx-content strong { font-weight: 700; color: var(--accent); }\n.wx-content em { font-style: italic; color: var(--accent); }\n.wx-footer {\n  margin-top: 3em;\n  padding-top: 1em;\n  border-top: 1px solid var(--table-border, #e2e8f0);\n  color: var(--text);\n  opacity: 0.5;\n  font-size: 0.85em;\n  text-align: center;\n}\n.wx-minimal-light { /* per-template overrides go here */ }\n/* Magazine classic: 首字下沉 */\n.wx-minimal-light.wx-magazine-classic .wx-content > p:first-of-type::first-letter {\n  font-size: 3em;\n  float: left;\n  line-height: 1;\n  margin-right: 8px;\n  margin-top: 4px;\n  color: var(--accent);\n  font-weight: 700;\n}\n/* Magazine interview: 引用块强化 */\n.wx-minimal-light.wx-magazine-interview .wx-content blockquote {\n  font-size: 1.1em;\n  font-style: italic;\n  text-align: center;\n}\n/* Business data: 表格斑马纹 */\n.wx-minimal-light.wx-magazine-data .wx-content tbody tr:nth-child(even),\n.wx-minimal-light.wx-business-data .wx-content tbody tr:nth-child(even) {\n  background: var(--table-stripe, rgba(0,0,0,0.02));\n}\n/* Tech terminal: 等宽字体贯穿 */\n.wx-minimal-light.wx-tech-terminal .wx-article {\n  font-family: var(--font-family);\n}\n.wx-minimal-light.wx-tech-terminal .wx-content code,\n.wx-minimal-light.wx-tech-terminal .wx-content pre {\n  font-family: var(--font-family);\n}\n</style>\n</head>\n<body class="wx-minimal-light">\n<article class="wx-article">\n  <header class="wx-cover">{{cover}}</header>\n  <h1 class="wx-title">{{title}}</h1>\n  <div class="wx-author">{{author}}</div>\n  <section class="wx-content">{{content}}</section>\n  <footer class="wx-footer">本文由公众号助手生成</footer>\n</article>\n</body>\n</html>', '{"bg": "#ffffff", "text": "#222222", "accent": "#111111", "code-bg": "#f3f4f6", "padding": "32px", "code-font": "Menlo, Consolas, monospace", "code-text": "#1f2937", "font-size": "16px", "max-width": "680px", "font-family": "-apple-system, \'PingFang SC\', \'Hiragino Sans GB\', sans-serif", "line-height": "1.85", "bg-secondary": "#fafafa", "table-border": "#e5e7eb", "heading-weight": "700"}', NULL, NULL, 1, 1, 0, 1, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
  (1, '极简灰调', 'minimal', '浅灰底 + 蓝灰强调,适合职场、工具类内容。', '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>{{title}}</title>\n<style>\n/* 模板样式 — 元素级 CSS + css_variables var(--*) 主题切换. */\nbody { background: var(--bg); color: var(--text); }\n.wx-article {\n  font-family: var(--font-family);\n  font-size: var(--font-size);\n  line-height: var(--line-height);\n  padding: var(--padding);\n  max-width: var(--max-width);\n  margin: 0 auto;\n  word-wrap: break-word;\n  overflow-wrap: break-word;\n}\n.wx-cover { margin: 0 0 1.2em 0; }\n.wx-cover img { width: 100%; border-radius: 6px; display: block; }\n.wx-title {\n  font-size: 1.6em;\n  font-weight: 700;\n  color: var(--accent);\n  border-bottom: 2px solid var(--accent);\n  padding-bottom: 0.5em;\n  margin: 1em 0 0.5em;\n  line-height: 1.3;\n}\n.wx-author {\n  color: var(--text);\n  opacity: 0.7;\n  font-size: 0.9em;\n  margin-bottom: 1.5em;\n  text-align: right;\n}\n.wx-content h1 {\n  font-size: 1.5em;\n  color: var(--accent);\n  border-left: 4px solid var(--accent);\n  padding-left: 12px;\n  margin: 2em 0 1em;\n  font-weight: var(--heading-weight, 700);\n}\n.wx-content h2 {\n  font-size: 1.3em;\n  color: var(--accent);\n  margin: 1.8em 0 0.8em;\n  font-weight: 600;\n}\n.wx-content h3 {\n  font-size: 1.15em;\n  color: var(--accent);\n  margin: 1.5em 0 0.6em;\n  font-weight: 600;\n}\n.wx-content h4, .wx-content h5, .wx-content h6 {\n  font-size: 1.05em;\n  color: var(--accent);\n  margin: 1.3em 0 0.5em;\n  font-weight: 600;\n}\n.wx-content p { margin: 1.2em 0; }\n.wx-content blockquote {\n  margin: 1.5em 0;\n  padding: 1em 1.5em;\n  background: var(--bg-secondary, rgba(0,0,0,0.03));\n  border-left: 4px solid var(--accent);\n  border-radius: 0 6px 6px 0;\n  color: var(--text);\n  opacity: 0.95;\n}\n.wx-content code {\n  background: var(--code-bg);\n  color: var(--code-text, var(--accent));\n  padding: 0.2em 0.4em;\n  border-radius: 3px;\n  font-family: var(--code-font, monospace);\n  font-size: 0.9em;\n}\n.wx-content pre {\n  background: var(--code-bg);\n  padding: 1.2em;\n  margin: 1.5em 0;\n  border-radius: 6px;\n  overflow: auto;\n  line-height: 1.5;\n}\n.wx-content pre code {\n  background: none;\n  padding: 0;\n  color: var(--code-text);\n  font-size: 0.9em;\n}\n.wx-content ul, .wx-content ol {\n  margin: 1em 0;\n  padding-left: 2em;\n}\n.wx-content li {\n  margin: 0.4em 0;\n  line-height: var(--line-height);\n}\n.wx-content ul li { list-style-type: var(--list-marker, disc); }\n.wx-content ol li { list-style-type: decimal; }\n.wx-content ul ul, .wx-content ol ol,\n.wx-content ul ol, .wx-content ol ul {\n  margin: 0.3em 0;\n}\n.wx-content table {\n  width: 100%;\n  border-collapse: collapse;\n  margin: 1.5em 0;\n  font-size: 0.95em;\n}\n.wx-content th, .wx-content td {\n  border: 1px solid var(--table-border, #e2e8f0);\n  padding: 8px 12px;\n  text-align: left;\n}\n.wx-content th {\n  background: var(--code-bg);\n  font-weight: 600;\n  color: var(--accent);\n}\n.wx-content a {\n  color: var(--accent);\n  text-decoration: none;\n  border-bottom: 1px solid var(--accent);\n}\n.wx-content a:hover {\n  opacity: 0.8;\n}\n.wx-content img {\n  max-width: 100%;\n  border-radius: 6px;\n  margin: 1.5em auto;\n  display: block;\n}\n.wx-content hr {\n  border: 0;\n  border-top: 1px solid var(--table-border, #e2e8f0);\n  margin: 2em 0;\n}\n.wx-content strong { font-weight: 700; color: var(--accent); }\n.wx-content em { font-style: italic; color: var(--accent); }\n.wx-footer {\n  margin-top: 3em;\n  padding-top: 1em;\n  border-top: 1px solid var(--table-border, #e2e8f0);\n  color: var(--text);\n  opacity: 0.5;\n  font-size: 0.85em;\n  text-align: center;\n}\n.wx-minimal-gray { /* per-template overrides go here */ }\n/* Magazine classic: 首字下沉 */\n.wx-minimal-gray.wx-magazine-classic .wx-content > p:first-of-type::first-letter {\n  font-size: 3em;\n  float: left;\n  line-height: 1;\n  margin-right: 8px;\n  margin-top: 4px;\n  color: var(--accent);\n  font-weight: 700;\n}\n/* Magazine interview: 引用块强化 */\n.wx-minimal-gray.wx-magazine-interview .wx-content blockquote {\n  font-size: 1.1em;\n  font-style: italic;\n  text-align: center;\n}\n/* Business data: 表格斑马纹 */\n.wx-minimal-gray.wx-magazine-data .wx-content tbody tr:nth-child(even),\n.wx-minimal-gray.wx-business-data .wx-content tbody tr:nth-child(even) {\n  background: var(--table-stripe, rgba(0,0,0,0.02));\n}\n/* Tech terminal: 等宽字体贯穿 */\n.wx-minimal-gray.wx-tech-terminal .wx-article {\n  font-family: var(--font-family);\n}\n.wx-minimal-gray.wx-tech-terminal .wx-content code,\n.wx-minimal-gray.wx-tech-terminal .wx-content pre {\n  font-family: var(--font-family);\n}\n</style>\n</head>\n<body class="wx-minimal-gray">\n<article class="wx-article">\n  <header class="wx-cover">{{cover}}</header>\n  <h1 class="wx-title">{{title}}</h1>\n  <div class="wx-author">{{author}}</div>\n  <section class="wx-content">{{content}}</section>\n  <footer class="wx-footer">本文由公众号助手生成</footer>\n</article>\n</body>\n</html>', '{"bg": "#f7f7f8", "text": "#2d3748", "accent": "#4a5568", "code-bg": "#edf2f7", "padding": "28px", "code-font": "Menlo, Consolas, monospace", "code-text": "#2d3748", "font-size": "16px", "max-width": "700px", "font-family": "-apple-system, \'PingFang SC\', sans-serif", "line-height": "1.8", "bg-secondary": "#ffffff", "table-border": "#e2e8f0", "heading-weight": "700"}', NULL, NULL, 1, 1, 0, 2, '2026-08-07 07:31:45', '2026-08-07 07:31:45'),
