ight: 8px;\n  margin-top: 4px;\n  color: var(--accent);\n  font-weight: 700;\n}\n/* Magazine interview: 引用块强化 */\n.wx-literary-book.wx-magazine-interview .wx-content blockquote {\n  font-size: 1.1em;\n  font-style: italic;\n  text-align: center;\n}\n/* Business data: 表格斑马纹 */\n.wx-literary-book.wx-magazine-data .wx-content tbody tr:nth-child(even),\n.wx-literary-book.wx-business-data .wx-content tbody tr:nth-child(even) {\n  background: var(--table-stripe, rgba(0,0,0,0.02));\n}\n/* Tech terminal: 等宽字体贯穿 */\n.wx-literary-book.wx-tech-terminal .wx-article {\n  font-family: var(--font-family);\n}\n.wx-literary-book.wx-tech-terminal .wx-content code,\n.wx-literary-book.wx-tech-terminal .wx-content pre {\n  font-family: var(--font-family);\n}\n</style>\n</head>\n<body class="wx-literary-book">\n<article class="wx-article">\n  <header class="wx-cover">{{cover}}</header>\n  <h1 class="wx-title">{{title}}</h1>\n  <div class="wx-author">{{author}}</div>\n  <section class="wx-content">{{content}}</section>\n  <footer class="wx-footer">本文由公众号助手生成</footer>\n</article>\n</body>\n</html>', '{"bg": "#f4ecd8", "text": "#3d2914", "accent": "#7c2d12", "code-bg": "#ebe1c8", "padding": "36px", "code-font": "Georgia, \'Songti SC\', serif", "code-text": "#7c2d12", "font-size": "17px", "max-width": "680px", "font-family": "\'Songti SC\', \'Source Han Serif SC\', Georgia, serif", "line-height": "2.0", "bg-secondary": "#ebe1c8", "table-border": "#d4c8a8", "heading-weight": "700"}', NULL, NULL, 1, 1, 0, 10, '2026-08-07 07:31:45', '2026-08-07 07:31:46'),
